pub fn discover(root: &Path) -> Result<Vec<Requirement>> {
    let root = root.canonicalize().map_err(|e| e.to_string())?;
    let config: toml::Value = read_book(&root, Path::new("book.toml"))?
        .parse()
        .map_err(|e| format!("book.toml: {e}"))?;
    if config.get("book").is_some_and(|book| !book.is_table()) {
        return Err("book must be a TOML table".into());
    }
    let src = match config.get("book").and_then(|b| b.get("src")) {
        Some(value) => value.as_str().ok_or("book.src must be a string")?,
        None => "src",
    };
    let summary = read_book(&root, &Path::new(src).join("SUMMARY.md"))?;
    let mut chapters = BTreeSet::new();
    for event in Parser::new(&summary) {
        if let Event::Start(Tag::Link { dest_url, .. }) = event {
            let dest = dest_url.as_ref();
            if dest.is_empty()
                || dest.starts_with('#')
                || dest.starts_with("//")
                || dest.split_once(':').is_some_and(|(scheme, _)| {
                    scheme.starts_with(|c: char| c.is_ascii_alphabetic())
                        && scheme
                            .chars()
                            .all(|c| c.is_ascii_alphanumeric() || "+-.".contains(c))
                })
            {
                continue;
            }
            let dest = dest.split('#').next().unwrap();
            chapters.insert(Path::new(src).join(dest));
        }
    }
    let mut found: BTreeMap<String, Requirement> = BTreeMap::new();
    for chapter in chapters {
        let source = read_book(&root, &chapter)?;
        let path = chapter.to_string_lossy().replace('\\', "/");
        for requirement in extract(&path, &source)? {
            if let Some(previous) = found.get(&requirement.id) {
                return Err(format!(
                    "duplicate requirement {} in {} and {}",
                    requirement.id, previous.path, path
                ));
            }
            found.insert(requirement.id.clone(), requirement);
        }
    }
    if found.is_empty() {
        return Err("no requirements found in the book; refusing a vacuous check".into());
    }
    Ok(found.into_values().collect())
}

fn read_book(root: &Path, relative: &Path) -> Result<String> {
    if relative.is_absolute() {
        return Err(format!(
            "book paths must be relative: {}",
            relative.display()
        ));
    }
    let path = root
        .join(relative)
        .canonicalize()
        .map_err(|e| format!("{}: {e}", relative.display()))?;
    if !path.starts_with(root) {
        return Err(format!(
            "book path escapes repository: {}",
            relative.display()
        ));
    }
    fs::read_to_string(path).map_err(|e| format!("{}: {e}", relative.display()))
}

fn discovers_only_listed_chapters_and_rejects_duplicates() {
    let f = Fixture::new();
    f.write("chapters/unused.md", "{req}`unused.rule` Not in book.");
    assert_eq!(discover(&f.0).unwrap().len(), 1);
    f.write(
        "chapters/SUMMARY.md",
        "- [First](nested/contract.md)\n- [Second](second.md)\n",
    );
    f.write("chapters/second.md", "{req}`test.rule` Duplicate.");
    assert!(discover(&f.0).unwrap_err().contains("duplicate"));
}

fn default_source_external_links_and_nested_summary() {
    let f = Fixture::new();
    f.write("book.toml", "[book]\ntitle = 'Test'\n");
    f.write("src/SUMMARY.md", "# Summary\n- [Root](root.md)\n  - [Nested](deep/leaf.md#anchor)\n- [Web](//example.com/book)\n- [Mail](mailto:a@example.com)\n- [URN](urn:example:test)\n- [Draft]()\n- [Anchor](#here)\n");
    f.write("src/root.md", "{req}`test.root` Root.");
    f.write("src/deep/leaf.md", "{req}`test.leaf` Leaf.");
    let ids: Vec<_> = discover(&f.0).unwrap().into_iter().map(|r| r.id).collect();
    assert_eq!(ids, ["test.leaf", "test.root"]);
    f.write("book.toml", "book = 3");
    assert!(discover(&f.0).unwrap_err().contains("table"));
    f.write("book.toml", "[invalid");
    assert!(discover(&f.0).is_err());
}

fn parent_relative_chapters_are_allowed_only_inside_repository() {
    let f = Fixture::new();
    f.write("chapters/SUMMARY.md", "- [Shared](../shared/chapter.md)");
    f.write("shared/chapter.md", "{req}`test.shared` Shared contract.");
    assert_eq!(discover(&f.0).unwrap()[0].id, "test.shared");
    f.write("book.toml", "[book]\nsrc = './src/../chapters'");
    assert_eq!(discover(&f.0).unwrap()[0].id, "test.shared");
    let other = Fixture::new();
    let sibling = other.0.file_name().unwrap().to_str().unwrap();
    f.write(
        "chapters/SUMMARY.md",
        &format!("- [Escape](../../{sibling}/chapters/nested/contract.md)"),
    );
    assert!(discover(&f.0).unwrap_err().contains("escapes repository"));
}
